const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '2' },
      { kind: 'text', payload: '3' },
      { kind: 'text', payload: '4' },
      { kind: 'text', payload: '1' },
      { kind: 'text', payload: '2' },
      { kind: 'text', payload: '3' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var cols = 4;
    var rows = 3;
    var cell = Math.min((W - 120) / cols, (H - 120) / rows);
    if (!(cell > 10)) { cell = 10; }
    var gridW = cell * cols;
    var gridH = cell * rows;
    var x0 = (W - gridW) / 2 + 12;
    var y0 = (H - gridH) / 2 + 12;
    if (x0 < 38) { x0 = 38; }
    if (y0 < 38) { y0 = 38; }

    var cmds = [];
    var i, j;
    for (i = 0; i <= cols; i++) {
      var x = x0 + i * cell;
      cmds.push(['M', x, y0]);
      cmds.push(['L', x, y0 + gridH]);
    }
    for (j = 0; j <= rows; j++) {
      var y = y0 + j * cell;
      cmds.push(['M', x0, y]);
      cmds.push(['L', x0 + gridW, y]);
    }

    var ink = '#26354a';
    var children = [
      { type: 'path', pathId: 'grid', fill: ink, stroke: { width: 2, cap: 'butt', join: 'miter' } }
    ];

    for (i = 0; i < cols; i++) {
      children.push({
        type: 'label',
        contentId: metrics[i].contentId,
        anchor: { x: x0 + (i + 0.5) * cell, y: y0 - 10 },
        hAlign: 'center',
        vAlign: 'bottom',
        color: ink
      });
    }
    for (j = 0; j < rows; j++) {
      children.push({
        type: 'label',
        contentId: metrics[cols + j].contentId,
        anchor: { x: x0 - 12, y: y0 + (j + 0.5) * cell },
        hAlign: 'right',
        vAlign: 'middle',
        color: ink
      });
    }

    return {
      schemaVersion: 1,
      sceneId: 'grid-3x4',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [{ id: 'grid', commands: cmds }],
      root: { type: 'group', children: children }
    };
  }
};
